import axios from 'axios'

const IDENTITER_URL = '/api'

export default {
  namespaced: true,

  state: {
    token: localStorage.getItem('token') || null,
    user: JSON.parse(localStorage.getItem('user')) || null,
    isAuthenticated: !!localStorage.getItem('token'),
    pendingVerification: null
  },

  mutations: {
    SET_TOKEN(state, token) {
      state.token = token
      state.isAuthenticated = !!token
      if (token) {
        localStorage.setItem('token', token)
      } else {
        localStorage.removeItem('token')
      }
    },
    SET_USER(state, user) {
      state.user = user
      if (user) {
        localStorage.setItem('user', JSON.stringify(user))
      } else {
        localStorage.removeItem('user')
      }
    },
    SET_PENDING_VERIFICATION(state, data) {
      state.pendingVerification = data
    }
  },

  actions: {
    async register({ commit }, userData) {
      try {
        const response = await axios.post(`${IDENTITER_URL}/auth/register`, userData)
        commit('SET_PENDING_VERIFICATION', {
          email: userData.email,
          message: 'Veuillez vérifier votre email pour le code de vérification'
        })
        return response.data
      } catch (error) {
        throw error.response?.data || error.message
      }
    },

    async verifyEmail({ commit }, { email, verificationCode }) {
      try {
        const response = await axios.post(`${IDENTITER_URL}/auth/verify-email`, {
          email,
          verificationCode
        })
        commit('SET_PENDING_VERIFICATION', null)
        return response.data
      } catch (error) {
        throw error.response?.data || error.message
      }
    },

    async login({ commit }, credentials) {
      try {
        const response = await axios.post(`${IDENTITER_URL}/auth/login`, credentials)

        // Si 2FA est activé, on attend le code
        if (response.data.requires2FA) {
          commit('SET_PENDING_VERIFICATION', {
            email: credentials.email,
            message: 'Veuillez entrer le code de vérification envoyé par email',
            requires2FA: true
          })
          return response.data
        }

        const { token, user } = response.data
        commit('SET_TOKEN', token)
        commit('SET_USER', user)
        commit('SET_PENDING_VERIFICATION', null)
        return response.data
      } catch (error) {
        throw error.response?.data || error.message
      }
    },

    async verify2FA({ commit }, { email, code }) {
      try {
        const response = await axios.post(`${IDENTITER_URL}/auth/verify-2fa`, {
          email,
          code
        })
        const { token, user } = response.data
        commit('SET_TOKEN', token)
        commit('SET_USER', user)
        commit('SET_PENDING_VERIFICATION', null)
        return response.data
      } catch (error) {
        throw error.response?.data || error.message
      }
    },

    logout({ commit }) {
      commit('SET_TOKEN', null)
      commit('SET_USER', null)
      commit('SET_PENDING_VERIFICATION', null)
    }
  },

  getters: {
    isAuthenticated: state => state.isAuthenticated,
    user: state => state.user,
    token: state => state.token,
    pendingVerification: state => state.pendingVerification
  }
}
